/// options_window.h — Map ▸ Options and Overlay ▸ Options, the counterpart of
/// OptionsWindow.swift.
#pragma once

#include <gtkmm.h>

#include <functional>
#include <map>
#include <string>

#include "fv_desk_host.h"

namespace peregrine {

/// The pages of one options model in a sidebar and the selected page's
/// fields generated by type, with Restore Defaults, Cancel, Apply and OK.
/// Holds no option values of its own: a control re-reads its field from the
/// host after every change, so a value the core clamps shows clamped.
/// Closing the window discards what was not applied.
class OptionsWindow : public Gtk::Window {
 public:
  /// `kind` is a `fv::desk::HostOptionsKind`; `host` must outlive the window.
  OptionsWindow(fv::desk::DeskHost& host, int kind, Gtk::Window& parent);

  /// Re-reads the model after the core opened it afresh.
  void Reload();
  /// Shows page `page`.
  void SelectPage(int page);
  int page() const { return page_; }
  /// Offers `value` for field `key` of the current page, as its control would.
  void Set(const std::string& key, const std::string& value);
  /// Applies the changes; false (with an alert) when the core refused.
  bool Apply();
  void Ok();
  void RestoreDefaults();

  /// The current page's control for `key`, or null.
  Gtk::Widget* control(const std::string& key) const;
  Gtk::Button& apply_button() { return apply_; }

 private:
  void ShowPage();
  Gtk::Widget* MakeControl(const fv::desk::HostOptionsField& f, int index);
  Gtk::Entry* MakeEntry(const std::string& key);
  void ChoosePath(const std::string& key);
  void UpdateApply();

  fv::desk::DeskHost& host_;
  const int kind_;
  Gtk::Box box_{Gtk::Orientation::VERTICAL};
  Gtk::Box panes_{Gtk::Orientation::HORIZONTAL};
  Gtk::ScrolledWindow side_scroll_;
  Gtk::ListBox sidebar_;
  Gtk::ScrolledWindow form_scroll_;
  Gtk::Button defaults_{"Restore Defaults"};
  Gtk::Button cancel_{"Cancel"};
  Gtk::Button apply_{"Apply"};
  Gtk::Button ok_{"OK"};
  int page_ = 0;
  /// Set while controls are filled from the model, so their signals are not edits.
  bool loading_ = false;
  /// The current page's controls, field indexes and fillers, by key.
  std::map<std::string, Gtk::Widget*> controls_;
  std::map<std::string, int> field_index_;
  std::map<std::string, std::function<void(const std::string& value)>> fill_;
};

}  // namespace peregrine
